import{_ as a,o as p,a as n,b as t}from"./app.C41L12d5.js";const l="/ascendc.github.io/assets/mx_format.CouIMwqv.png",c="/ascendc.github.io/assets/mx_matrix_computation_demo.Cj6B-Qd5.png",d="/ascendc.github.io/assets/mx_scaleA_format.X5bR1vdH.png",e="/ascendc.github.io/assets/mx_scaleB_format.Bf_pV_sL.png",i="/ascendc.github.io/assets/index_generation.DSUKMMCK.png",r="/ascendc.github.io/assets/density_B_matrix_demo.CKfxucHh.png",M=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算分形介绍","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_fractal_intro/cube_compute_fractal_intro"},{"text":"辅助矩阵分形格式详解","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_fractal_intro/aux_cube_fractal_format_details"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_fractal_intro/aux_cube_fractal_format_details.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_fractal_intro/aux_cube_fractal_format_details.md","outlineHeaders":[{"level":2,"title":"MX系数矩阵","slug":"MX系数矩阵","link":"#MX系数矩阵"},{"level":2,"title":"4选2稀疏索引矩阵","slug":"4选2稀疏索引矩阵","link":"#4选2稀疏索引矩阵"}],"lastUpdated":1787050286000}'),o={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_fractal_intro/aux_cube_fractal_format_details.md"};function _(h,s,u,g,b,m){return p(),n("div",null,[...s[0]||(s[0]=[t('<div><article class="markdown-body"><h1>辅助矩阵分形格式详解<span id="ZH-CN_TOPIC_0000002538231118"></span></h1><div data-filter="950"><h2 id="MX系数矩阵">MX系数矩阵<span id="zh-cn_topic_0000002563445163_section648585413300"></span><a class="header-anchor" href="#MX系数矩阵">​</a></h2><p>针对Ascend 950PR/Ascend 950DT产品：</p><p>浮点数在科学计算、图像处理、神经网络等领域应用广泛。以AI训练为例，现有的浮点数格式或数值范围不足，或精度不高，这影响了模型的收敛速度和性能。如果要同时满足数值范围和精度的要求，将会导致内存占用过大，从而增加数据存储和传输的成本。基于此种情况，业内提出了一种新的浮点数格式——微缩放（Microscaling，MX）格式。MX格式的浮点数可以支持更低比特位宽的AI训练和推理，并且占用的内存更少。符合MX标准的数据格式在使用8位或更低比特位的情况下，能够实现稳健的AI训练和推理模型精度。</p><p>MX格式是一种块数据格式，若干个数据可以组成一个块（或者一个组），数据以块为单位。MX格式的数据由三部分构成：</p><ul><li>共享缩放因子X，位宽为w bits；</li><li>私有元素P<sub>i</sub>，位宽为d bits；</li><li>块大小k，表示多少个低比特数据形成一个块；</li></ul><p>所有k个元素P<sub>i</sub>有相同的位宽和数据类型，并且共享一个缩放因子X，每个包含k个元素的块可以使用（w+k*d）位进行编码。元素的数据类型和缩放因子可以独立选择。</p><p>下图为MX格式的浮点数的数据结构，S、E和M分别用于表示浮点数的符号、指数和尾数字段的值。其中，共享缩放因子X是一个用于整个数据块的缩放比例因子，它决定了数据块中所有元素的动态范围。通过引入共享缩放因子，MX格式的数据能够在保持低位宽的同时，灵活地表示不同范围的数据。块大小k指的是组成一个数据块（或组）的低比特数据的数量。私有元素P<sub>i</sub>是指数据块中的每个低比特数据元素。这些元素经过缩放因子X的调整后，共同表示了一个高精度的浮点数或整数。</p><p><strong>图1</strong> MX格式组成示意图<span id="zh-cn_topic_0000002563445163_fig3385175571011"></span><br><img src="'+l+'" alt title="MX格式组成示意图"></p><p>MXMmad为带有量化系数X的矩阵乘法，即左矩阵和右矩阵均有对应的量化系数矩阵，左量化系数矩阵scaleA和右量化系数矩阵scaleB。计算公式为：C = (scaleA ⊗ A) * (scaleB ⊗ B) + Bias，“⊗”表示广播乘法，左/右矩阵与左/右量化系数矩阵做乘积时，K方向上每32个元素共享一个量化因子。如下图所示，其中A为左矩阵，形状为[M, K]；scaleA为左量化系数矩阵，形状为[M, K/32]；B为右矩阵，形状为[K, N]；scaleB为右量化系数矩阵，形状为[K/32, N]。</p><p><strong>图2</strong> MX矩阵乘示意图<span id="zh-cn_topic_0000002563445163_fig33303533712"></span><br><img src="'+c+`" alt title="MX矩阵乘示意图"></p><ul><li><p><strong>MX scaleA系数矩阵分形介绍</strong><span id="section_mx_scalea_fractal_format"></span></p><ul><li><p><strong>物理位置：</strong> Global Memory/L1 Buffer/Unified Buffer（UB）：保存离线/在线生成左矩阵量化系数数据。</p></li><li><p><strong>设计原理：</strong> MX矩阵乘法中A矩阵与scaleA矩阵物理地址上一一映射，LoadData（MX矩阵搬运）接口要求在L1 Buffer中scaleA矩阵满足行读取需求，因此在L1 Buffer上scaleA矩阵为按行存储的小z大Z排布（Zz）。</p></li><li><p><strong>格式转换过程：</strong> 假设原始A矩阵大小为（M, K），则对应的scaleA矩阵大小为（M, K/32），scaleA矩阵被分为M1 * K1个分形，按照row major（行主序）排布，形状如Z字形；每个分形内部有M0 * K0个元素，按照row major（行主序）排布，形状如Z字形，所以这种数据格式称为Zz格式。其中，(M0, K0)表示一个分形的shape，其分形需要与L0A_MX Buffer物理内存排布保持一致，且数据类型必须为fp8_e8m0_t，shape为16x2。</p><p>通过公式表达转换过程如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">M</span><span class="p">,</span> <span class="n">K</span><span class="o">/</span><span class="mi">32</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">pad</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">M1</span> <span class="o">*</span> <span class="n">M0</span><span class="p">,</span> <span class="n">K1</span> <span class="o">*</span> <span class="n">K0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">reshape</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">M1</span><span class="p">,</span> <span class="n">M0</span><span class="p">,</span> <span class="n">K1</span><span class="p">,</span> <span class="n">K0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">transpose</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">M1</span><span class="p">,</span> <span class="n">K1</span><span class="p">,</span> <span class="n">M0</span><span class="p">,</span> <span class="n">K0</span><span class="p">)</span>
</code></pre></div></li><li><p><strong>分形大小约束：</strong> 数据类型为fp8_e8m0_t，分形大小为16x2（M0，K0）</p></li></ul><p>如下图所示，若GM上scaleA矩阵为ND排布，可以通过ND2NZ.b16/DN2NZ.b16指令搬运到L1 Buffer，确保L1 Buffer上分形为Zz排布，满足LoadData（MX矩阵搬运）接口要求。</p><p><strong>图3</strong> scaleA矩阵在不同位置上的排布格式<span id="zh-cn_topic_0000002563445163_fig6871154411446"></span><br><img src="`+d+`" alt title="scaleA矩阵在不同位置上的排布格式"></p></li><li><p><strong>MX scaleB系数矩阵分形介绍</strong><span id="section_mx_scaleb_fractal_format"></span></p><ul><li><p><strong>物理位置：</strong> Global Memory/L1 Buffer/UB：保存离线/在线生成右矩阵量化系数数据。</p></li><li><p><strong>设计原理：</strong> MX矩阵乘法中B矩阵与scaleB矩阵物理地址上一一映射，LoadData（MX矩阵搬运）接口要求在L1 Buffer上scaleB矩阵满足列读取需求，因此在L1 Buffer上scaleB矩阵为按列存储的大N小n排布（Nn）。</p></li><li><p><strong>格式转换过程：</strong> 假设原始B矩阵大小为（K, N），则对应的scaleB矩阵大小为（K/32, N），scaleB矩阵被分为K1 * N1个分形，按照column major（列主序）排布，形状如N字形；每个分形内部有K0 * N0个元素，按照column major（列主序）排布，形状如n字形，所以这种数据格式称为Nn格式。其中，（K0, N0）表示一个分形的shape，其分形需要与L0B_MX Buffer物理内存排布保持一致，且数据类型必须为fp8_e8m0_t，shape为2x16。</p><p>通过公式表达转换过程如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K</span><span class="o">/</span><span class="mi">32</span><span class="p">,</span> <span class="n">N</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">pad</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K1</span> <span class="o">*</span> <span class="n">K0</span><span class="p">,</span> <span class="n">N1</span> <span class="o">*</span> <span class="n">N0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">reshape</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K1</span><span class="p">,</span> <span class="n">K0</span><span class="p">,</span> <span class="n">N1</span><span class="p">,</span> <span class="n">N0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">transpose</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">N1</span><span class="p">,</span> <span class="n">K1</span><span class="p">,</span> <span class="n">N0</span><span class="p">,</span> <span class="n">K0</span><span class="p">)</span>
</code></pre></div></li><li><p><strong>分形大小约束：</strong> 数据类型为fp8_e8m0_t，分形大小为2x16（K0，N0）</p></li></ul><p>如下图所示，若Global Memory（GM）上scaleB矩阵为ND排布，可以通过ND2NZ.b16/DN2NZ.b16指令搬运到L1 Buffer，确保L1 Buffer上分形为Nn排布，满足LoadData（MX矩阵搬运）接口要求。</p><p><strong>图4</strong> scaleB矩阵在不同位置上的排布格式<span id="zh-cn_topic_0000002563445163_fig599218260112"></span><br><img src="`+e+'" alt title="scaleB矩阵在不同位置上的排布格式"></p></li></ul><p>具体实现可参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/load_data_2dmx_l12l0">MXmmad样例</a>。</p></div><div data-filter="A3,910b"><h2 id="4选2稀疏索引矩阵">4选2稀疏索引矩阵<span id="zh-cn_topic_0000002563445163_section1873692415233"></span><a class="header-anchor" href="#4选2稀疏索引矩阵">​</a></h2><p>针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品：</p><ul><li>定义：原始B矩阵稠密化过程中生成的索引矩阵。假设原始B矩阵每4个元素有至少2个零元素，稠密化的B矩阵是过滤掉2个零的稠密矩阵。</li><li>场景：通常存在于Global Memory（GM）中。在进行sparse矩阵运算前，通常需要离线生成并将其转换为大Z小n格式（Zn）以适配Cube单元。</li><li>生成过程：如下图所示，对于原始矩阵B中的每4个元素，将在index矩阵中生成2个2位索引，并按照以下规则进行编码。索引必须在{0, 1, 2}范围内。 <strong>图5</strong> index生成示意图<span id="zh-cn_topic_0000002563445163_fig1423214854720"></span><br><img src="'+i+'" alt title="index生成示意图"><ul><li>第一个索引用于指示前3个元素中第1个非零元素的相对位置。</li><li>第二个索引用于指示第2个非零元素在后3个元素中的相对位置。</li><li>索引矩阵中的一个uint8的元素是由4个uint2_t组合而成的，例如上图：生成的索引数据为1 2 0 1 ，索引数据在Global Memory（GM）地址中的排布从高位到低位为1 0 2 1 ，其中1 0 2 1（对应索引矩阵前四位1 2 0 1）为一个uint8_t。</li></ul></li></ul><p><strong>图6</strong> 稠密化B矩阵示意图<span id="zh-cn_topic_0000002563445163_fig1115556103916"></span><br><img src="'+r+`" alt title="稠密化B矩阵示意图"></p><p>稠密化算法规则具体可参考下表。其中，“-”表示不关心该位置上的值，因为其后续Sparse Mmad计算过程中会被过滤。</p><table><thead><tr><th>示例</th><th>B矩阵元素0</th><th>B矩阵元素1</th><th>B矩阵元素2</th><th>B矩阵元素3</th><th>索引数据0</th><th>索引数据1</th></tr></thead><tbody><tr><td rowspan="6">四个元素里面有两个非零元素</td><td>0</td><td>0</td><td>X</td><td>Y</td><td>2&#39;b10</td><td>2&#39;b10</td></tr><tr><td>0</td><td>X</td><td>0</td><td>Y</td><td>2&#39;b01</td><td>2&#39;b10</td></tr><tr><td>X</td><td>0</td><td>0</td><td>Y</td><td>2&#39;b00</td><td>2&#39;b10</td></tr><tr><td>0</td><td>X</td><td>Y</td><td>-</td><td>2&#39;b01</td><td>2&#39;b01</td></tr><tr><td>X</td><td>0</td><td>Y</td><td>-</td><td>2&#39;b00</td><td>2&#39;b01</td></tr><tr><td>X</td><td>Y</td><td>-</td><td>-</td><td>2&#39;b00</td><td>2&#39;b00</td></tr><tr><td rowspan="4">四个元素里面有一个非零元素</td><td>0</td><td>0</td><td>0</td><td>X</td><td>2&#39;b00</td><td>2&#39;b10</td></tr><tr><td>0</td><td>0</td><td>X</td><td>0</td><td>2&#39;b10</td><td>2&#39;b00</td></tr><tr><td>0</td><td>X</td><td>0</td><td>0</td><td>2&#39;b01</td><td>2&#39;b00</td></tr><tr><td>X</td><td>0</td><td>0</td><td>0</td><td>2&#39;b00</td><td>2&#39;b00</td></tr><tr><td>四个元素里面没有非零元素</td><td>0</td><td>0</td><td>0</td><td>0</td><td>2&#39;b00</td><td>2&#39;b00</td></tr></tbody></table><ul><li><p><strong>物理位置：</strong> GM/L1 Buffer：保存离线生成好的索引矩阵数据。</p></li><li><p><strong>设计原理：</strong> 列读取需求：sparse矩阵乘法中B矩阵与Index矩阵物理地址上一一映射，LoadDataWithSparse指令要求在L1 Buffer上B矩阵与Index矩阵满足列读取需求，因此在GM/L1 Buffer上Index矩阵为按列存储的大Z小n排布（Zn）。</p></li><li><p><strong>格式转换过程：</strong> 假设原始B矩阵大小为（K, N），则经过4选2稠密化后的B矩阵与Index矩阵大小为（K/2, N），Index矩阵被分为K1 * N1个分形，按照row major（行主序）排布，形状如Z字形；每个分形内部有N0 * K0个元素，按照column major（列主序）排布，形状如N字形，所以这种数据格式称为Zn格式。其中，(N0, K0)表示一个分形的shape，其分形需要与B矩阵分形保持一致，B矩阵数据类型为int8_t，其小分形shape为16*32，Index矩阵分形中每个uint8_t数据由4个uint2_t元素拼接而成，其元素与B矩阵元素地址一一对应，因此分形shape也为16*32，但大小为128Byte。</p><p>通过公式表达转换过程如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K</span><span class="o">/</span><span class="mi">2</span><span class="p">,</span> <span class="n">N</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">pad</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K1</span> <span class="o">*</span> <span class="n">K0</span><span class="p">,</span> <span class="n">N1</span> <span class="o">*</span> <span class="n">N0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">reshape</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K1</span><span class="p">,</span> <span class="n">K0</span><span class="p">,</span> <span class="n">N1</span><span class="p">,</span> <span class="n">N0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">transpose</span><span class="o">-&gt;</span><span class="p">(</span><span class="err">…</span><span class="p">,</span> <span class="n">B</span><span class="p">,</span> <span class="n">K1</span><span class="p">,</span> <span class="n">N1</span><span class="p">,</span> <span class="n">N0</span><span class="p">,</span> <span class="n">K0</span><span class="p">)</span>
</code></pre></div></li><li><p><strong>分形大小约束：</strong> 存储为uint8数据类型时，分形大小为16x8（N0，K0）。</p></li></ul></div></article></div>`,1)])])}const B=a(o,[["render",_]]);export{M as __pageData,B as default};
